#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
double reward[2]={1,2},gamma=0.9;
double transition[2][2]={{0.8,0.2},{0.3,0.7}};
double a=1-gamma*transition[0][0],b=-gamma*transition[0][1];
double c=-gamma*transition[1][0],d=1-gamma*transition[1][1];
double det=a*d-b*c;
if(fabs(det)<1e-12)return 1;
double value0=(d*reward[0]-b*reward[1])/det;
double value1=(a*reward[1]-c*reward[0])/det;
cout<<"Bellman solution "<<value0<<" "<<value1<<endl;
    return 0;
}

