#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> policy={0.6,0.3,0.8},behavior={0.4,0.5,0.5};
double ratio=1;
for(int t=0;t<int(policy.size());t++){
    if(behavior[t]<=0)return 1;
    ratio*=policy[t]/behavior[t];
    cout<<"Time "<<t<<" cumulative ratio "<<ratio<<endl;
}
vector<double> weights={0.5,1,2,0.8};
double sum=0,squares=0;
for(double w:weights){sum+=w;squares+=w*w;}
cout<<"Importance-weight ESS "<<sum*sum/squares<<endl;
    return 0;
}

