#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<vector<double>> standardized={{1,-1},{0.5,0.8},{-0.3,-0.6}};
double a=0.04,b=0.9,unconditionalCorrelation=0.2;
double q11=1,q22=1,q12=unconditionalCorrelation;
double previous[2]={0,0};
for(int t=0;t<int(standardized.size());t++){
    if(t>0){
        q11=(1-a-b)+a*previous[0]*previous[0]+b*q11;
        q22=(1-a-b)+a*previous[1]*previous[1]+b*q22;
        q12=(1-a-b)*unconditionalCorrelation+a*previous[0]*previous[1]+b*q12;
    }
    double correlation=q12/sqrt(q11*q22);
    cout<<"Time "<<t<<" conditional correlation "<<correlation<<endl;
    previous[0]=standardized[t][0];previous[1]=standardized[t][1];
}
    return 0;
}

