#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

int main(){
vector<double> oldWeight={0.6,0.4},target={0.3,0.7};
vector<double> previousReturn={0.1,-0.05},nextReturn={0.02,-0.01};
double prevGrowth=0;
for(int i=0;i<2;i++)prevGrowth+=oldWeight[i]*(1+previousReturn[i]);
double traded=0,portfolioReturn=0;
for(int i=0;i<2;i++){
    double drifted=oldWeight[i]*(1+previousReturn[i])/prevGrowth;
    traded+=fabs(target[i]-drifted);
    portfolioReturn+=target[i]*nextReturn[i];
}
double commission=0.0005;
double netGrowth=(1-traded*commission)*(1+portfolioReturn);
cout<<"Gross traded "<<traded<<" net growth "<<netGrowth<<endl;
    return 0;
}
